    for (slot, target) in OWN_HOOKS.iter() {
        match slot.compare_exchange(0, index + 1, Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => {}
            Err(held) if held == index + 1 => {}
            Err(_) => continue,
        }
        target.store(replacement, Ordering::Release);
        return;
    }
