/// Start archive retirement in every build, with optional diagnostic heartbeat output.
pub fn start() {
    let started = if TRACE_ENABLED { now_ms() } else { 0 };
    let spawned = std::thread::Builder::new()
        .name("practice-heartbeat".into())
        .stack_size(0x10000)
        .spawn(move || {
            crate::engine::compat::logging::writer_started();
            let drains_per_beat = (HEARTBEAT_INTERVAL.as_millis() / DRAIN_INTERVAL.as_millis()) as u64;
            let mut beat = 0u64;
            let mut drains = 0u64;
            loop {
                std::thread::sleep(DRAIN_INTERVAL);
                // R-A0b: seam outcomes resolved after the install line (runtime-only rows, late NROs).
                crate::runtime::seams::seam_install::report_late();
                // Diagnostic build: the hook-sharing drill's stand-in run counts, when they change.
                #[cfg(feature = "diag")]
                crate::swap_native::seam_drill::report_counts(now_ms());
                crate::engine::compat::logging::drain();
                drains += 1;
                if !drains.is_multiple_of(drains_per_beat) {
                    continue;
                }
                let now = now_ms();
                // Revision 33: housekeeping off the game threads — release inflated layout archives
                // the game finished copying (training::ui).
                crate::runtime::lobby::training::ui::release_stale_archives(now);
                if TRACE_ENABLED {
                    beat += 1;
                    let probes: Vec<String> = PROBES.iter().map(|probe| probe.summary(now)).collect();
                    crate::engine::compat::logging::diagnostic(format_args!(
                        "[Heartbeat] n={} up={}s mode={:?} {} {}",
                        beat,
                        now.saturating_sub(started) / 1000,
                        crate::runtime::lobby::game_mode::current(),
                        probes.join(" "),
                        crate::engine::compat::logging::ring_stats()
                    ));
                }
            }
        });
    match spawned {
        Ok(_) => {
            if TRACE_ENABLED {
                crate::engine::compat::logging::diagnostic(format_args!(
                    "[Heartbeat] thread started interval={}s probes={}",
                    HEARTBEAT_INTERVAL.as_secs(),
                    PROBES.len()
                ));
            }
        }
        Err(error) => {
            crate::engine::compat::logging::diagnostic(format_args!("[Heartbeat] thread unavailable: {error}"));
            crate::engine::compat::logging::diagnostic(format_args!(
                "[PracticeDiagnostics] writer=caller heartbeat_thread=unavailable"
            ));
        }
    }
}

